<template><div><CrudQueryCard :model="query" @search="load" @reset="reset"><el-form-item :label="t('trade.tenantId')"><TenantSelect v-model="query.tenantId" /></el-form-item><el-form-item :label="t('trade.settleAsset')"><el-input v-model="query.settleAsset" clearable/></el-form-item><el-button v-perm="'trade:insurance-fund-account:update'" type="primary" @click="edit()">{{t('common.add')}}</el-button></CrudQueryCard><el-card shadow="never"><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="symbolId" :label="t('trade.symbolId')"/><el-table-column prop="settleAsset" :label="t('trade.settleAsset')"/><el-table-column prop="fundUserId" :label="t('trade.fundUserId')"/><el-table-column prop="walletType" :label="t('trade.walletType')"/><el-table-column prop="adlEnabled" :label="t('trade.adlEnabled')"/><el-table-column prop="status" :label="t('trade.status')"/><el-table-column :label="t('common.actions')"><template #default="{row}"><el-button link @click="edit(row)">{{t('common.edit')}}</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" :title="t('trade.insuranceFundAccounts')" width="520"><el-form :model="form" label-width="150"><el-form-item :label="t('trade.tenantId')"><TenantSelect v-model="form.tenantId"/></el-form-item><el-form-item :label="t('trade.symbolId')"><el-input-number v-model="form.symbolId" :min="0"/></el-form-item><el-form-item :label="t('trade.settleAsset')"><el-input v-model="form.settleAsset"/></el-form-item><el-form-item :label="t('trade.fundUserId')"><el-input-number v-model="form.fundUserId" :min="1"/></el-form-item><el-form-item :label="t('trade.walletType')"><el-input-number v-model="form.walletType" :min="1"/></el-form-item><el-form-item :label="t('trade.adlEnabled')"><el-switch v-model="adl"/></el-form-item></el-form><template #footer><el-button @click="visible=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="save">{{t('common.confirm')}}</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{useI18n}from'vue-i18n';import{apiTradeListInsuranceFundAccounts,apiTradeSetInsuranceFundAccount}from'@/api/trade';import type{InsuranceFundAccount}from'@/services';const{t}=useI18n(),loading=ref(false),visible=ref(false),rows=ref<InsuranceFundAccount[]>([]),query=reactive({tenantId:undefined as number|undefined,settleAsset:''}),form=reactive({id:0,tenantId:0,symbolId:0,settleAsset:'USDT',fundUserId:0,walletType:3,adlEnabled:2,status:1,version:0});const adl=computed({get:()=>form.adlEnabled===1,set:v=>form.adlEnabled=v?1:2});async function load(){loading.value=true;try{const r=await apiTradeListInsuranceFundAccounts({...query,limit:100});rows.value=r.data||[]}finally{loading.value=false}}function reset(){query.tenantId=undefined;query.settleAsset='';load()}function edit(r?:InsuranceFundAccount){Object.assign(form,r||{id:0,tenantId:query.tenantId||0,symbolId:0,settleAsset:'USDT',fundUserId:0,walletType:3,adlEnabled:2,status:1,version:0});visible.value=true}async function save(){await apiTradeSetInsuranceFundAccount(form);ElMessage.success(t('common.success'));visible.value=false;load()}onMounted(load)
</script>
